<script setup lang="ts">
import {projects} from '~/data/projects'; useSeoMeta({title:'Selected Work | Webonova',description:'Client projects and Webonova concept work across hospitality, events, construction, and platforms.'}); const route=useRoute(),router=useRouter(); const status=ref(String(route.query.status||'all')),industry=ref(String(route.query.industry||'all')),sort=ref(String(route.query.sort||'newest')); watch([status,industry,sort],()=>router.replace({query:{status:status.value==='all'?undefined:status.value,industry:industry.value==='all'?undefined:industry.value,sort:sort.value==='newest'?undefined:sort.value}})); const visible=computed(()=>projects.filter(p=>(status.value==='all'||p.status===status.value)&&(industry.value==='all'||p.industry===industry.value)).sort((a,b)=>sort.value==='oldest'?a.year-b.year:sort.value==='client'?(a.status==='client'?-1:1):sort.value==='concept'?(a.status==='concept'?-1:1):b.year-a.year)); const client=projects.filter(p=>p.status==='client').length
</script>
<template><div><section class="work-hero section"><p class="eyebrow">WORK / SELECTED PROJECTS</p><h1>Digital work,<br>thoughtfully <em>built.</em></h1><p class="lead">Client projects and self-initiated concepts across hospitality, commerce, construction, and meaningful digital experiences.</p><p class="red">{{client}} client project · {{projects.length-client}} concept projects · More coming</p></section><section class="filters section"><div class="tabs"><button v-for="s in [['all','All Work'],['client','Client Work'],['concept','Concept Projects']]" :key="s[0]" :class="{active:status===s[0]}" @click="status=s[0]">{{s[1]}}</button></div><label>Industry<select v-model="industry"><option value="all">All Industries</option><option v-for="x in ['Hospitality','Events','Construction','Platforms']" :key="x">{{x}}</option></select></label><label>Sort<select v-model="sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="client">Client work first</option><option value="concept">Concept projects first</option></select></label><span>{{visible.length}} projects</span></section><section class="projects section"><article v-for="p in visible" :key="p.title"><img :src="p.thumbnail" :alt="p.alt" width="900" height="560" :loading="p.number<'03'?'eager':'lazy'"><b class="red">{{p.number}}</b><h2>{{p.title}}</h2><div><small :class="['badge',p.status]">{{p.status==='client'?'CLIENT WORK':'CONCEPT PROJECT'}}</small><span>{{p.industry}} / {{p.category}}</span><span>{{p.year}}</span></div><p>{{p.description}}</p><p class="tags"><small v-for="s in p.services" :key="s">{{s}}</small></p><a :href="p.url" target="_blank" rel="noopener noreferrer" :aria-label="`${p.cta}: ${p.title} (opens in a new tab)`">{{p.cta}} ↗</a></article><p v-if="!visible.length" class="empty" role="status">No projects match the selected filters.</p></section><aside class="concept-note section">ⓘ Concept projects are self-initiated demonstrations created to explore design direction, interaction, and development capabilities.</aside><section class="dark capabilities section"><h2>Every project,<br>built as a system.</h2><article v-for="x in ['Strategy','UX and UI','Responsive development','CMS and integrations','Performance','Accessibility']" :key="x"><h3>{{x}}</h3></article></section><section class="statement cta-row"><span>Have a project worth building?</span><NuxtLink class="btn ghost-light" to="/contact">Start a project →</NuxtLink></section></div></template>
